    }

    colorArray = Color._getCorrectColor(colorArray);
    if (colorArray[0] === cColorSpace) {
      return colorArray;
    }

    if (colorArray[0] === "T") {
      return this.convert(this.black, cColorSpace);
    }

    return ColorConverters[`${colorArray[0]}_${cColorSpace}`](
      colorArray.slice(1)
    );
  }

